it.each(['omp', 'opencode'] as const)(
    'copies a stopped and running %s chat without loading or prompting its original',
    async (agent) => {
      const rig = await open(agent)
      const request = {
        ...input,
        identity: { ...input.identity, agent },
        accountHome:
          agent === 'omp'
            ? input.accountHome
            : { kind: 'opencode' as const, locator: { kind: 'unmanaged' as const } }
      }
      const expected = {
        sessionId: 'copy-1',
        ...(agent === 'omp' ? { filePath: '/account-a/sessions/copy-1.jsonl' } : {})
      }
      await expect(rig.adapter.copyConversation(request)).resolves.toEqual(expected)
      expect(rig.child().agent.frames.map((frame) => frame.method)).toEqual([
        'initialize',
        'session/fork'
      ])
      expect(rig.sent('session/fork')[0]?.params).toEqual({
        sessionId: PROVIDER_SESSION,
        cwd: '/workspace/project',
        mcpServers: []
      })
      expect(rig.child().closes).toBe(1)
      await rig.acquire()
      const chat = rig.child()
      const frames = [...chat.agent.frames]
      await expect(rig.adapter.copyConversation(request)).resolves.toEqual(expected)
      expect(chat.agent.frames).toEqual(frames)
      expect(chat.closes).toBe(0)
      expect(rig.child()).not.toBe(chat)
      expect(rig.child().closes).toBe(1)
    }
  )

it('permits another copy after unproven cleanup and retries the retained child at shutdown', async () => {
    const rig = await openAcpAdapterRig({ spec: acpLaunchSpecFor('omp')!, initialize: FORKS })
    rigs.push(rig)
    const copying = rig.adapter.copyConversation(input)
    await vi.waitFor(() => expect(rig.sent('session/fork')).toHaveLength(1))
    const child = rig.child()
    child.proveClose = async () => false
    child.agent.reply(rig.sent('session/fork')[0]!, { sessionId: 'copy-1' })
    await expect(copying).resolves.toHaveProperty('sessionId', 'copy-1')
    const next = rig.adapter.copyConversation(input)
    await vi.waitFor(() => {
      expect(rig.child()).not.toBe(child)
      expect(rig.sent('session/fork')).toHaveLength(1)
    })
    rig.child().agent.reply(rig.sent('session/fork')[0]!, { sessionId: 'copy-2' })
    await expect(next).resolves.toHaveProperty('sessionId', 'copy-2')
    child.proveClose = async () => {
      child.exit()
      return true
    }
    await rig.adapter.closeAll()
    expect(child.closes).toBe(2)
  })

it('bounds an unanswered fork and closes its temporary process', async () => {
    const children: FakeAcpChild[] = []
    const spec = acpLaunchSpecFor('omp')!
    await expect(
      copyAcpConversation(
        {
          spec,
          dataDirectory: '/orca-data',
          readLaunch: async () => ({
            spec,
            command: 'fake',
            args: [],
            cwd: '/repo',
            env: {},
            envToDelete: [],
            fullAccess: false,
            resume: null
          }),
          connect: (...args: ConstructorParameters<typeof FakeAcpChild>) => {
            const child = new FakeAcpChild(...args)
            child.agent.on('initialize', (frame) =>
              child.agent.reply(frame, { protocolVersion: 1, ...FORKS })
            )
            children.push(child)
            return child
          }
        },
        input,
        { timeoutMs: 10, track: () => {} }
      )
    ).rejects.toThrow('OMP could not copy this chat')
    expect(children.map((child) => child.closes)).toEqual([1])
  })

it.each(['opencode', 'opencode2'] as const)(
    'refuses to copy a %s chat whose arguments route to a server, before starting OpenCode',
    async (agent) => {
      const spec = acpLaunchSpecFor(agent)!
      const connect = vi.fn()
      await expect(
        copyAcpConversation(
          {
            spec,
            dataDirectory: '/orca-data',
            resolveLaunchArgs: () => ['--server', 'https://other-host:4096'],
            readLaunch: async () => {
              throw new Error('not reached')
            },
            connect
          },
          {
            ...input,
            identity: { ...input.identity, agent },
            accountHome: { kind: 'opencode', locator: { kind: 'unmanaged' } }
          },
          { track: () => {} }
        )
      ).rejects.toThrow('--server')
      expect(connect).not.toHaveBeenCalled()
    }
  )

it('reads a spawn with its description, its spawning turn and nothing it cannot show', () => {
    expect(
      grokSubagentNotification({
        sessionUpdate: 'subagent_spawned',
        subagent_id: 'subagent-1',
        child_session_id: 'subagent-1',
        parent_prompt_id: 'prompt-1',
        subagent_type: 'general-purpose',
        description: 'Count note lines',
        model: 'grok-4.7'
      })
    ).toEqual({ id: 'subagent-1', state: 'working', label: 'Count note lines', turn: 'prompt-1' })
  })

it('labels a spawn with no description by its type', () => {
    expect(
      grokSubagentNotification({
        sessionUpdate: 'subagent_spawned',
        subagent_id: 'subagent-1',
        subagent_type: 'explore'
      })
    ).toEqual({ id: 'subagent-1', state: 'working', label: 'explore' })
  })

it('reads progress as tokens only', () => {
    expect(
      grokSubagentNotification({
        sessionUpdate: 'subagent_progress',
        subagent_id: 'subagent-1',
        tokens_used: 4091
      })
    ).toEqual({ id: 'subagent-1', tokens: 4091 })
  })

it.each([
    ['completed', { state: 'completed', result: '4' }],
    ['failed', { state: 'failed' }],
    ['cancelled', { state: 'stopped' }],
    ['something-new', {}]
  ] as const)('reads a %s finish', (status, expected) => {
    expect(
      grokSubagentNotification({
        sessionUpdate: 'subagent_finished',
        subagent_id: 'subagent-1',
        status,
        output: status === 'completed' ? '4' : undefined,
        error: status === 'completed' ? undefined : 'Subagent was cancelled',
        tokens_used: 0
      })
    ).toEqual({ id: 'subagent-1', ...expected })
  })

it('ignores every other update', () => {
    expect(grokSubagentNotification({ sessionUpdate: 'turn_completed' })).toBeUndefined()
    expect(grokSubagentNotification({ sessionUpdate: 'subagent_spawned' })).toBeUndefined()
  })

it('maps the extension notification, and leaves a replayed one to the load', () => {
    const params = {
      sessionId: 'session-1',
      update: { sessionUpdate: 'subagent_progress', subagent_id: 'subagent-1', tokens_used: 9 }
    }
    expect(GROK_ACP_DIALECT.notification?.('_x.ai/session_notification', params, 1)).toEqual({
      disposition: 'map',
      subagents: [{ id: 'subagent-1', tokens: 9 }]
    })
    expect(
      GROK_ACP_DIALECT.notification?.(
        'x.ai/session/update',
        { ...params, _meta: { isReplay: true } },
        1
      )
    ).toMatchObject({ disposition: 'map', replay: true })
  })

it('ends a foreground spawn with its reply, the machine blocks removed', () => {
    expect(
      grokToolSubagents(
        finished({
          rawOutput: {
            type: 'SubagentCompleted',
            subagent_id: 'subagent-1',
            output: `4${SUBAGENT_RESULT_TAIL}`
          }
        }),
        tool('spawn_subagent', spawnInput)
      )
    ).toEqual([{ id: 'subagent-1', state: 'completed', label: 'Count note lines', result: '4' }])
  })

it('keeps a background spawn running from its acknowledgement, labelled by the prompt when undescribed', () => {
    expect(
      grokToolSubagents(
        finished({
          rawOutput: {
            type: 'Text',
            text: 'Subagent started in background.\nsubagent_id: subagent-2\ndescription: x\n'
          }
        }),
        tool('spawn_subagent', { prompt: 'List the files\nand more' })
      )
    ).toEqual([{ id: 'subagent-2', state: 'working', label: 'List the files' }])
  })

it('reads nothing from a spawn that has not finished', () => {
    expect(
      grokToolSubagents(finished({ status: 'in_progress' }), tool('spawn_subagent', spawnInput))
    ).toEqual([])
  })

it('settles known subagents from an output read, and leaves its shell tasks alone', () => {
    const update = finished({
      rawOutput: {
        type: 'TaskOutput',
        MultiResult: {
          results: [
            {
              task_id: 'subagent-1',
              command: '[subagent:general-purpose] List folder files',
              status: 'completed',
              output: `notes.txt, README.md${SUBAGENT_RESULT_TAIL}`
            },
            {
              task_id: 'subagent-2',
              command: '[subagent:general-purpose] Sleeper',
              status: 'cancelled',
              output: 'Subagent was cancelled'
            },
            { task_id: 'shell-1', command: 'sleep 5', status: 'completed', exit_code: 0 }
          ]
        }
      }
    })
    expect(grokToolSubagents(update, tool('get_command_or_subagent_output'))).toEqual([
      { id: 'subagent-1', state: 'completed', knownOnly: true, result: 'notes.txt, README.md' },
      { id: 'subagent-2', state: 'stopped', knownOnly: true }
    ])
    expect(
      grokToolBackgroundTasks(update, tool('get_command_or_subagent_output')).map(
        (task) => task.taskId
      )
    ).toEqual(['shell-1'])
  })

it('stops a subagent a kill reports killed, and never makes it a background task', () => {
    const update = finished({
      rawOutput: {
        type: 'KillTask',
        Result: { task_id: 'subagent-1', command: '[subagent:explore] Look', outcome: 'killed' }
      }
    })
    expect(grokToolSubagents(update, tool('kill_command_or_subagent'))).toEqual([
      { id: 'subagent-1', state: 'stopped', knownOnly: true }
    ])
    expect(grokToolBackgroundTasks(update, tool('kill_command_or_subagent'))).toEqual([])
  })

it('infers a kill with no result from the ids it named', () => {
    expect(
      grokToolSubagents(
        finished({}),
        tool('kill_command_or_subagent', { task_ids: ['subagent-1', 'subagent-1'] })
      )
    ).toEqual([{ id: 'subagent-1', state: 'stopped', knownOnly: true }])
  })

it('leaves a tool without a command echo as it came', () => {
    const update: ToolCallUpdate = {
      toolCallId: 'call-1',
      status: 'completed',
      rawOutput: { content: [{ type: 'text', text: 'file body' }], details: {} },
      content: [text('file body')]
    }
    expect(normalize(update)).toBe(update)
  })

it('keeps a result that itself starts with "$ "', () => {
    const update: ToolCallUpdate = {
      toolCallId: 'call-1',
      status: 'completed',
      rawOutput: { content: [{ type: 'text', text: '$ 5.00' }], details: {} },
      content: [text('$ 5.00')]
    }
    expect(normalize(update)).toBe(update)
  })

it.each([0, 3])('keeps an exit %s notice when OMP sent no matching detail', (code) => {
    const output = `done\n\nCommand exited with code ${code}`
    const update = normalize({
      toolCallId: 'call-1',
      status: 'completed',
      rawOutput: {
        content: [{ type: 'text', text: output }],
        details: { wallTimeMs: 12 }
      },
      content: [text('$ ./run'), text(output)]
    })
    expect(update).toMatchObject({
      content: [],
      rawOutput: { stdout: output, exitCode: 0 }
    })
  })

it('shows exit 0 for a foreground command that completed, since OMP omits a zero exit', () => {
    expect(normalize(command('completed', { wallTimeMs: 12 })).rawOutput).toMatchObject({
      stdout: 'ok',
      exitCode: 0
    })
    expect(
      normalize(command('completed', { wallTimeMs: 0, signal: null })).rawOutput
    ).toMatchObject({
      exitCode: 0
    })
  })

it('infers no exit code for a command that is running, timed out, signalled or in the background', () => {
    for (const update of [
      command('in_progress', { wallTimeMs: 12 }),
      command('completed', { wallTimeMs: 12, timedOut: true }),
      command('completed', { wallTimeMs: 12, signal: 'SIGTERM' }),
      command('completed', { wallTimeMs: 12, async: { jobId: 'job-1' } }),
      command('completed', { wallTimeMs: 12 }, { command: './run', async: true })
    ]) {
      expect(normalize(update).rawOutput).not.toHaveProperty('exitCode')
    }
  })

it('infers no exit code without foreground timing metadata', () => {
    for (const details of [undefined, {}, { signal: null }]) {
      const update = normalize({
        toolCallId: 'call-1',
        status: 'completed',
        rawOutput: { content: [{ type: 'text', text: 'ok' }], ...(details ? { details } : {}) },
        content: [text('$ ./run'), text('ok')]
      })
      expect(update.rawOutput).toMatchObject({ stdout: 'ok' })
      expect(update.rawOutput).not.toHaveProperty('exitCode')
    }
  })

it('does not confuse OMP v18.4 service-start completion with a process exit', () => {
    for (const timing of [{}, { wallTimeMs: 12 }]) {
      const update = normalize({
        toolCallId: 'service-call',
        status: 'completed',
        rawOutput: {
          content: [{ type: 'text', text: 'web: running pid=123 ready' }],
          details: {
            ...timing,
            service: { name: 'web', state: 'running', ready: true, timedOut: false, pid: 123 }
          }
        },
        content: [text('$ python3 -m http.server 8765'), text('web: running pid=123 ready')]
      })
      expect(update.rawOutput).toMatchObject({ stdout: 'web: running pid=123 ready' })
      expect(update.rawOutput).not.toHaveProperty('exitCode')
    }
  })

it('leaves an existing generic command result intact', () => {
    for (const result of [
      { exitCode: 3 },
      { exit_code: 3 },
      { stdout: 'original' },
      { stderr: 'error' },
      { output_for_prompt: 'original' },
      { signal: 'SIGTERM' },
      { timed_out: true }
    ]) {
      const update = command('completed', { wallTimeMs: 12 })
      update.rawOutput = {
        ...result,
        content: [{ type: 'text', text: 'ok' }],
        details: { wallTimeMs: 12 }
      }
      expect(normalize(update)).toBe(update)
    }
  })

it("keeps a failed command's reported exit code", () => {
    const update = normalize({
      toolCallId: 'call-1',
      status: 'failed',
      rawOutput: {
        content: [{ type: 'text', text: 'hi\n\nCommand exited with code 3' }],
        details: { exitCode: 3 }
      },
      content: [text('$ ./run'), text('hi\n\nCommand exited with code 3')]
    })
    expect(update.rawOutput).toMatchObject({ stdout: 'hi', exitCode: 3 })
  })

