      probeVersion
    })
    await expect(
      probe({ kind: 'opencode', locator: { kind: 'unmanaged' } })
    ).rejects.toBeInstanceOf(AgentModelCatalogListingStoppedError)
    expect(probeVersion).not.toHaveBeenCalled()
  })

