    })
    cleanup.push(() => rig.adapter.closeAll())
    await rig.acquire()
    expect(rig.adapter.backgroundTaskStops(SESSION)?.supportsTaskStop).toBe(false)
    expect(rig.child().closed).toBe(false)
  })

