it('ends the turn at the exit itself; the provider-exit batch only reports on it', async () => {
    const rig = await midReply()
    rig.child.exit()
    const settled = await settledCrash(rig)
    expectOneTurnScopedCutShortRow(settled)
    // The child's own end landed first, interrupted at the exit and never `unverifiable`: the host
    // has no turn or call of it left to revise.
    expect(
      settled.batch.mutations.map((mutation) => mutation.kind === 'item' && mutation.body.kind)
    ).toEqual(['status'])
    await rig.host.close(SESSION, 'user-close')
  })

it('is unverifiable only until the exit is proven; the provider-exit batch then revises the turn', async () => {
    const rig = await midReply()
    // The child outlives its stream until Orca's close of it is proven.
    let exitNow: () => void = () => undefined
    rig.child.proveClose = () =>
      new Promise((resolve) => {
        exitNow = () => {
          rig.child.exit()
          resolve(true)
        }
      })
    rig.child.agent.close()
    await waitFor(async () =>
      expect((await rig.turns()).map((turn) => turn.state)).toEqual(['unverifiable'])
    )
    expect((await rig.rows()).filter((row) => row.body.kind === 'status')).toEqual([])

    exitNow()
    const settled = await settledCrash(rig)
    expectOneTurnScopedCutShortRow(settled)
    // The turn's revision, its call's and the row land together.
    const turnKey = settled.turn!.itemId
    expect(
      settled.batch.mutations.flatMap((mutation) =>
        mutation.kind === 'item' ? [journalLifecycleMutationItemId(mutation)] : []
      )
    ).toEqual(expect.arrayContaining([settled.statuses[0]!.itemId, turnKey]))
    // No later stale-session pass rewrites it: nothing is left for one.
    expect(rig.batches.filter((batch) => batch.settlementId.includes('stale-session'))).toEqual([])
    await rig.host.close(SESSION, 'user-close')
  })

it('shows a reply a crash cut off with the existing notice, never completed from what Grok saved', async () => {
    let resumed = false
    const { rig, host, fence, messages, exchange, ready } = await openHostRig({
      initialize: RESUMES,
      script: loads('complete saved reply', { loads: 0 }),
      deps: { resolveLaunch: launch(() => resumed) }
    })
    expect(await host.attach(CALLER, attachParams())).toMatchObject({ ok: true })
    await ready()
    resumed = true
    await exchange('complete', false)
    // Grok dies mid-reply; the host ends its record, which moves the chat's fence.
    const cutAt = fence()
    rig.child().exit()
    await waitFor(() => expect(fence()).toBeGreaterThan(cutAt))
    expect(await host.attach(CALLER, attachParams(fence()))).toMatchObject({ ok: true })
    await ready()
    await host.flushStreamedEvents(SESSION)
    expect(await messages()).toEqual(['hello', 'complete'])
    const rows = (await host.history({ sessionId: SESSION, direction: 'tail' })).page.items
    expect(rows.flatMap((row) => readAgentJournalTurn(row.body)?.state ?? [])).not.toContain(
      'completed'
    )
    // The transcript explains the cut the way a Claude or Codex chat's does.
    const transcript = withNativeChatCutTurnNotices(rows, { agentName: 'Grok' })
    expect(
      transcript.some(
        (row) =>
          row.body.kind === 'status' &&
          (row.itemId.includes('cut-turn-notice') ||
            readAgentSessionFailureFact(row.body.failure)?.kind === 'providerExited')
      )
    ).toBe(true)
    await host.close(SESSION, 'user-close')
  })

it('rejects a send meanwhile as never sent, and a later Stop does not turn the crash into one', async () => {
    const { rig, host, rows } = await openAttachedHostRig()
    const child = rig.child()
    await send(host, 'hello')
    const prompt = await rig.frame('session/prompt')
    child.agent.notify('session/update', replyChunk(promptIdOf(prompt), 'partial'))
    await rig.settle()
    let proves = false
    child.proveClose = async () => {
      if (proves) {
        child.exit()
      }
      return proves
    }
    child.stderr = 'panic: out of memory'
    // Both pipes close as the process dies, before its exit is seen.
    child.agent.close()
    await rig.settle()
    const next = await send(host, 'next')
    await waitFor(async () =>
      expect(
        (await host.journalSnapshot(SESSION)).submissions.find(
          (entry) => entry.clientMessageId === next
        )
      ).toMatchObject({
        dispatchState: 'rejected',
        reason: 'Grok stopped before this message was sent.'
      })
    )
    await stop(host)
    proves = true
    child.exit()
    await rig.settle()
    await host.flushStreamedEvents(SESSION)
    const transcript = withNativeChatCutTurnNotices(await rows(), { agentName: 'Grok' })
    // The crash's own notice, as for any crash; not a Stop's.
    expect(
      transcript.flatMap((row) =>
        row.body.kind === 'status'
          ? [{ text: row.body.text, failure: readAgentSessionFailureFact(row.body.failure)?.kind }]
          : []
      )
    ).toEqual([
      {
        text: 'Grok stopped while this response was in progress. You can continue in this conversation.',
        failure: 'providerExited'
      }
    ])
    await host.close(SESSION, 'user-close')
  })

it('retains a published startup child whose close is unproven and retries before another spawn', async () => {
    const { rig, host } = await openHostRig({ script: (agent) => agent.on('initialize', () => {}) })
    expect(await host.attach(CALLER, attachParams())).toMatchObject({ ok: true })
    await rig.frame('initialize')
    const child = rig.child()
    child.proveClose = vi.fn(async () => false)
    try {
      await expect(host.close(SESSION, 'user-close')).rejects.toThrow('eviction failed')
      expect(child.exited).toBe(false)
      expect(rig.spawned.filter((step) => step === 'spawn')).toHaveLength(1)
    } finally {
      child.proveClose = vi.fn(async () => {
        child.exit()
        return true
      })
      await host.close(SESSION, 'user-close')
    }
    expect(child.exited).toBe(true)
    await host.send(CALLER, {
      envelope: envelope('agentSession.send', { body: hello }),
