it('runs `opencode acp` as an ACP client with no question tool, whatever the user set', async () => {
    const launch = await resolver(openCodeRecord(UNMANAGED), {
      launchEnv: { OPENCODE_CLIENT: 'tui', OPENCODE_ENABLE_QUESTION_TOOL: 'true' }
    })({ identity })
    expect(launch).toMatchObject({ command: '/resolved/opencode', args: ['acp'] })
    expect(launch.env).toMatchObject({
      OPENCODE_CLIENT: 'acp',
      OPENCODE_ENABLE_QUESTION_TOOL: 'false'
    })
  })

it("starts OpenCode with the user's own folders, database and inline credentials", async () => {
    const userEnv = {
      HOME: 'relative/home',
      XDG_DATA_HOME: 'relative/data',
      XDG_STATE_HOME: '/data/opencode-state',
      OPENCODE_DB: 'work.db',
      OPENCODE_AUTH_CONTENT: '{"secret":1}'
    }
    const launch = await resolver(openCodeRecord(UNMANAGED), {
      base: { XDG_DATA_HOME: '/elsewhere' },
      launchEnv: userEnv
    })({ identity })
    expect(launch.env).toMatchObject(userEnv)
    const child = createProviderSpawnSpec(
      {
        command: launch.command,
        args: launch.args,
        env: launch.env,
        envToDelete: [...STRUCTURED_CHILD_ENV_TO_DELETE, ...launch.envToDelete]
      },
      {},
      'darwin'
    ).env
    expect(child).toMatchObject(userEnv)
  })

it('leaves unset what the user left unset, whatever Orca itself inherited', async () => {
    const inheritedEnv = { OPENCODE_DB: '/elsewhere/other.db', OPENCODE_AUTH_CONTENT: '' }
    const launch = await resolver(openCodeRecord(UNMANAGED), { inheritedEnv })({ identity })
    expect(launch.env.XDG_DATA_HOME).toBeUndefined()
    expect(launch.env.OPENCODE_DB).toBeUndefined()
    const child = createProviderSpawnSpec(
      {
        command: launch.command,
        args: launch.args,
        env: launch.env,
        envToDelete: launch.envToDelete
      },
      inheritedEnv,
      'darwin'
    ).env
    expect(child.OPENCODE_DB).toBeUndefined()
    expect(child.OPENCODE_AUTH_CONTENT).toBeUndefined()
  })

it('points a managed profile at its own directories', async () => {
    const launch = await resolver(
      openCodeRecord({ kind: 'opencode', locator: { kind: 'managed', managedProfileId: PROFILE } })
    )({ identity })
    expect(launch.env).toMatchObject({
      XDG_DATA_HOME: `/profiles/${PROFILE}/data`,
      XDG_STATE_HOME: `/profiles/${PROFILE}/state`,
      OPENCODE_DB: 'opencode.db',
      OPENCODE_AUTH_CONTENT: ''
    })
  })

it("restores the user's own config directory over Orca's status overlay", async () => {
    const inheritedEnv = {
      OPENCODE_CONFIG_DIR: '/orca/overlay',
      ORCA_OPENCODE_CONFIG_DIR: '/orca/overlay',
      ORCA_OPENCODE_SOURCE_CONFIG_DIR: '/home/user/.config/opencode-mine',
      ORCA_OPENCODE_AGENT: 'opencode'
    }
    const launch = await resolver(openCodeRecord(UNMANAGED), { inheritedEnv })({ identity })
    expect(launch.env.OPENCODE_CONFIG_DIR).toBe('/home/user/.config/opencode-mine')
    const child = createProviderSpawnSpec(
      {
        command: launch.command,
        args: launch.args,
        env: launch.env,
        envToDelete: [...STRUCTURED_CHILD_ENV_TO_DELETE, ...launch.envToDelete]
      },
      inheritedEnv,
      'darwin'
    ).env
    expect(Object.keys(child).filter((key) => key.startsWith('ORCA_OPENCODE_'))).toEqual([])
    expect(child.OPENCODE_CONFIG_DIR).toBe('/home/user/.config/opencode-mine')
  })

it('drops an inherited overlay with no recorded source, so the default config is read', async () => {
    const inheritedEnv = {
      OPENCODE_CONFIG_DIR: '/orca/overlay',
      ORCA_OPENCODE_CONFIG_DIR: '/orca/overlay'
    }
    const launch = await resolver(openCodeRecord(UNMANAGED), { inheritedEnv })({ identity })
    const child = createProviderSpawnSpec(
      {
        command: launch.command,
        args: launch.args,
        env: launch.env,
        envToDelete: [...STRUCTURED_CHILD_ENV_TO_DELETE, ...launch.envToDelete]
      },
      inheritedEnv,
      'darwin'
    ).env
    expect(child.OPENCODE_CONFIG_DIR).toBeUndefined()
    expect(child.ORCA_OPENCODE_CONFIG_DIR).toBeUndefined()
  })

it("drops Orca's retired shared plugin directory an old shell still exports", () => {
    const env: Record<string, string> = {
      OPENCODE_CONFIG_DIR: '/orca-data/opencode-hooks/shared',
      ORCA_DATA_ACCOUNT_PROVIDER: 'opencode'
    }
    const removed = scrubOpenCodeAcpEnvironment(env, {}, '/orca-data')
    expect(env.OPENCODE_CONFIG_DIR).toBeUndefined()
    expect(removed).toEqual(
      expect.arrayContaining(['OPENCODE_CONFIG_DIR', 'ORCA_DATA_ACCOUNT_PROVIDER'])
    )
  })

it("keeps a config directory the user set for OpenCode's launches", async () => {
    const launch = await resolver(openCodeRecord(UNMANAGED), {
      launchEnv: { OPENCODE_CONFIG_DIR: '/home/user/team-config' },
      inheritedEnv: {
        OPENCODE_CONFIG_DIR: '/orca/overlay',
        ORCA_OPENCODE_CONFIG_DIR: '/orca/overlay'
      }
    })({ identity })
    expect(launch.env.OPENCODE_CONFIG_DIR).toBe('/home/user/team-config')
    expect(launch.envToDelete).not.toContain('OPENCODE_CONFIG_DIR')
  })

it('refuses a record that pins a single directory instead of an OpenCode account', async () => {
    await expect(
      resolver(openCodeRecord({ variable: 'XDG_DATA_HOME', path: '/data' }))({ identity })
    ).rejects.toThrow(/sessions pin opencode/)
  })

it.each(['2.0.21', '3.0.0', '3.0.0-beta.1'])('runs an `opencode` %s', async (version) => {
    const launch = await resolver(openCodeRecord(UNMANAGED), {
      probeVersion: async () => ({ version })
    })({ identity })
    expect(launch.args).toEqual(['acp'])
  })

it('runs when the version cannot be read; any real start failure reports itself', async () => {
    const launch = await resolver(openCodeRecord(UNMANAGED), {
      probeVersion: async () => ({ version: null })
    })({ identity })
    expect(launch.args).toEqual(['acp'])
  })

it('refuses a too-old release before spawning it, naming OpenCode and both versions', async () => {
    const launch = resolver(openCodeRecord(UNMANAGED), {
      probeVersion: async () => ({ version: '1.0.0' })
    })({ identity })
    await expect(launch).rejects.toBeInstanceOf(AgentCliInstallationError)
    await expect(launch).rejects.toThrow(
      'OpenCode 1.0.0 is too old for chats. Update to 1.18.31 or newer.'
    )
  })

it('asks the version of exactly the binary, folder and environment it spawns', async () => {
    const asked: Parameters<
      NonNullable<Parameters<typeof createAcpStructuredLaunchResolver>[1]['probeVersion']>
    >[0][] = []
    const launch = await resolver(openCodeRecord(UNMANAGED), {
      probeVersion: async (input) => (asked.push(input), { version: '1.18.31' })
    })({ identity })
    expect(asked).toEqual([{ program: launch.command, cwd: launch.cwd, env: launch.env }])
  })

it('runs `opencode2 acp` as an ACP client, and names its own sign-in command', async () => {
    const launch = await launchOn('2.0.28')
    expect(launch).toMatchObject({ command: '/resolved/opencode2', args: ['acp'] })
    expect(launch.env).toMatchObject({ OPENCODE_CLIENT: 'acp' })
    expect(OPENCODE2.loginCommand).toEqual(['opencode2', 'auth', 'login'])
  })

it('runs a later major or a pre-release of one', async () => {
    await expect(launchOn('3.0.0-beta.1')).resolves.toMatchObject({
      command: '/resolved/opencode2'
    })
  })

it.each(['1.18.35', '2.0.13', '2.0.14-rc.1'])('refuses %s as too old', async (version) => {
    await expect(launchOn(version)).rejects.toMatchObject({
      installation: { agent: 'opencode2', installedVersion: version, minimumVersion: '2.0.14' }
    })
  })

it('pins the record account home and searches the agent install dir', async () => {
    const { resolve, searched } = resolver(grokRecord())
    const launch = await resolve({ identity })
    expect(launch).toMatchObject({
      command: '/resolved/grok',
      args: ['agent', 'stdio'],
      cwd: '/repo/worktree',
      fullAccess: false,
      resume: null
    })
    expect(launch.env).toMatchObject({
      GROK_HOME: '/home/user/.grok-work',
      GROK_EXTRA: '1'
    })
    expect(searched[0]).toContain('/home/user/.grok-work/bin')
  })

it('creates a new ACP session after clear instead of probing the old session', async () => {
    const value = grokRecord({
      providerContextBoundary: { operationId: 'clear', afterFence: 2, clearedAt: 100 },
      providerHandleChain: []
    })
    const readJournal = () => {
      throw new Error('old history must not be sampled for resume')
    }
    const launch = await resolver(value, readJournal).resolve({ identity })
    expect(launch.resume).toBeNull()
  })

it("asks the agent to approve everything only under the chat's full access", async () => {
    const start = (permissionMode: 'ask' | 'full-access') =>
      resolver(grokRecord()).resolve({ identity, spawnToken: 'token', permissionMode })
    expect((await start('full-access')).args).toContain('--always-approve')
    expect((await start('ask')).args).not.toContain('--always-approve')
  })

it.each(ACP_LAUNCH_SPECS.map((spec) => spec.agent))(
    'gives %s chats a Full access mode',
    (agent) => {
      expect(agentChatPermissionModes(agent)?.modes).toContain('full-access')
    }
  )

it('resumes the chain head by its key, possibly unsaved only when this chat created it', async () => {
    const link = (origin: 'created' | 'resumed') => ({
      linkId: `link-${origin}`,
      origin,
      mintedAtFence: 1,
      observedAt: 1,
      handle: { transport: 'acp', agent: 'grok', nativeId: 'acp-1' }
    })
    const created = await resolver(grokRecord({ providerHandleChain: [link('created')] })).resolve({
      identity
    })
    const handle: AgentSessionProviderHandle = {
      transport: 'acp',
      agent: 'grok',
      nativeId: 'acp-1'
    }
    const key = agentSessionProviderHandleKey(handle)
    expect(created.resume).toMatchObject({ sessionId: 'acp-1', key })
    expect(created.resume?.mayBeUnsaved()).toBe(true)
    const resumed = await resolver(
      grokRecord({ providerHandleChain: [link('created'), link('resumed')] }),
      () => journalWithTurns()
    ).resolve({ identity })
    expect(resumed.resume).toMatchObject({ sessionId: 'acp-1', key })
    expect(resumed.resume?.mayBeUnsaved()).toBe(false)
  })

it('counts a created session as possibly unsaved only while the journal proves no turn on it', async () => {
    const created = grokRecord({
      providerHandleChain: [
        {
          linkId: 'link-created',
          origin: 'created',
          mintedAtFence: 1,
          observedAt: 1,
          handle: { transport: 'acp', agent: 'grok', nativeId: 'acp-1' }
        }
      ]
    })
    const unsaved = async (readJournal: () => JournalLoad | null) =>
      (await resolver(created, readJournal).resolve({ identity })).resume?.mayBeUnsaved()
    const reads: string[] = []
    const launch = await resolver(created, () => {
      reads.push('read')
      return null
    }).resolve({ identity })
    // Read only when asked: a reopen that works never replays the journal.
    expect(reads).toEqual([])
    expect(launch.resume?.mayBeUnsaved()).toBe(true)

    expect(await unsaved(() => journalWithTurns())).toBe(true)
    expect(await unsaved(() => journalWithTurns('acp-other'))).toBe(true)
    expect(await unsaved(() => journalWithTurns('acp-other', 'acp-1'))).toBe(false)
    // A journal that does not read whole, or at all, proves nothing.
    expect(
      await unsaved(() => ({
        ...journalWithTurns(),
        damage: { sequence: 3, cause: 'sequence-gap' }
      }))
    ).toBe(false)
    expect(await unsaved(() => ({ ...journalWithTurns(), newer: { sequence: 3 } }))).toBe(false)
    expect(
      await unsaved(() => {
        throw new Error('journal_closed')
      })
    ).toBe(false)
  })

it('names the lost conversations whose warning row no session of the chat wrote', async () => {
    const link = (nativeId: string, replaced?: string) => ({
      linkId: `link-${nativeId}`,
      origin: 'created' as const,
      mintedAtFence: 1,
      observedAt: 1,
      handle: { transport: 'acp', agent: 'grok', nativeId },
      ...(replaced
        ? {
            replaces: {
              key: agentSessionProviderHandleKey({
                transport: 'acp',
                agent: 'grok',
                nativeId: replaced
              }),
              reason: 'restore-failed',
              replacedAt: 1
            }
          }
        : {})
    })
    const lostKey = agentSessionProviderHandleKey({
      transport: 'acp',
      agent: 'grok',
      nativeId: 'acp-1'
    })
    const replaced = grokRecord({ providerHandleChain: [link('acp-1'), link('acp-2', 'acp-1')] })
    /** A journal holding the row for `lostKey`, written while `providerSession` ran. */
    const withRow = (providerSession: string): JournalLoad => {
      const load = journalWithTurns()
      const itemId = agentJournalItemKey(
        createLegacyProviderTimelineIdentityScheme({
          agent: 'grok',
          sessionId: identity.sessionId
        }).item({
          namespace: providerSession,
          family: 'item',
          key: { source: 'provider', value: acpSessionNotRestoredItem(lostKey) },
          thread: providerSession
        })
      )
      load.state.items.set(itemId, {
        itemId,
        revision: 1,
        sequence: 2,
        observedAt: 1,
        body: { kind: 'status', tone: 'warning', text: 'forgot' }
      })
      return load
    }
    const losses = async (record: AgentSessionRecord, readJournal: () => JournalLoad | null) =>
      (await resolver(record, readJournal).resolve({ identity })).resume?.unannouncedLosses()

    const reads: string[] = []
    // A chain that lost nothing never reads the journal.
    expect(
      await losses(grokRecord({ providerHandleChain: [link('acp-1')] }), () => {
        reads.push('read')
        return null
      })
    ).toEqual([])
    expect(reads).toEqual([])
    expect(await losses(replaced, () => null)).toEqual([lostKey])
    expect(await losses(replaced, () => journalWithTurns('acp-2'))).toEqual([lostKey])
    expect(await losses(replaced, () => withRow('acp-2'))).toEqual([])
    // A row the superseded replacement wrote still counts.
    expect(await losses(replaced, () => withRow('acp-gone'))).toEqual([])
    // A journal that does not read whole proves nothing, so no row is written.
    expect(
      await losses(replaced, () => ({
        ...journalWithTurns(),
        damage: { sequence: 3, cause: 'sequence-gap' }
      }))
    ).toEqual([])
    expect(
      await losses(replaced, () => {
        throw new Error('journal_closed')
      })
    ).toEqual([])
  })

it('refuses a record pinned to another host or another agent', async () => {
    const remote = grokRecord()
