it('holds mail without interrupting an answerable ACP question', async () => {
  const { host, rig } = await openAttachedHostRig()
  setStructuredAgentSessionHost(host)
  await send(host, 'work')
  await rig.frame('session/prompt')
  void rig.child().agent.request(601, 'x.ai/ask_user_question', {
    sessionId: PROVIDER_SESSION,
    toolCallId: 'question-1',
    questions: [{ question: 'Which file?', options: [{ label: 'a.ts' }] }]
  })
  const pointer = createStructuredMailboxPointerHost()
  await waitFor(() => expect(pointer.hasActionablePromptNow(SESSION)).toBe(true))
  const body: AgentJournalMessageItem = {
    ...hello,
    from: {
      kind: 'agent',
      senders: [],
      orchestration: { message: 'mail-notice', mailbox: 'run:r1', dispatchId: null, messages: [] }
    }
  }
  const operationId = mintAgentSessionOperationId(Date.now())
  const expectedRuntimeFence = host.deps.store.getRecord(SESSION)!.lease.runtimeFence
  expect(
    await pointer.send({
      sessionId: SESSION,
      dispatchId: null,
      operationId,
      expectedRuntimeFence,
      body
    })
  ).toEqual({ kind: 'held' })
  expect((await host.journalSnapshot(SESSION)).submissions).toHaveLength(1)
  expect(
    host.deps.store.readCommandReceipt(commandReceiptScope('any', 'global'), operationId)
  ).toMatchObject({ verdict: 'absent' })
  expect(framesOf(rig.child(), 'session/cancel')).toHaveLength(0)
  await host.close(SESSION, 'user-close')
})

it('starts the installed release first, else a copy beside every pinned member', async () => {
  const dataDirectory = await mkdtemp(join(tmpdir(), 'orca-acp-managed-'))
  const homePath = join(dataDirectory, 'home')
  const command = `orca-managed-${basename(dataDirectory)}`
  const root = join(dataDirectory, 'agent-runtimes', 'grok')
  const pin = {
    version: '1.0',
    url: 'https://example.test/grok-1.0.zip',
    archiveSha256: 'a'.repeat(64),
    archiveBytes: 10,
    members: [
      { path: command, sha256: 'b'.repeat(64), bytes: 6 },
      { path: 'harness', sha256: 'c'.repeat(64), bytes: 7 }
    ]
  }
  const spec = {
    ...GROK,
    command,
    managedRuntime: { label: 'Grok', root: () => root, pin: () => pin }
  }
  const spawn = async () => {
    const resolveLaunch = createAcpStructuredLaunchResolver(spec, {
      store: {
        getRecord: () => ({
          ...agentSessionRecordFixture(),
          provider: 'grok',
          providerHandleChain: [],
          accountHome: { variable: 'GROK_HOME', path: join(dataDirectory, '.grok') }
        }),
        pinLaunchDirectory: vi.fn()
      },
      readJournal: () => null,
      resolveEnvironment: async () => ({ PATH: '', HOME: homePath }),
      dataDirectory
    })
    const rig = await openAcpAdapterRig({ spec, deps: { resolveLaunch } })
    await rig.acquire()
    return rig.child().launch.command
  }
  await expect(spawn()).rejects.toMatchObject({ reason: 'runtimeNotInstalled' })

  // A server without its companion beside it is no copy.
  const localBin = join(homePath, '.local', 'bin')
  await mkdir(localBin, { recursive: true })
  await writeFile(join(localBin, command), '', { mode: 0o755 })
  await expect(spawn()).rejects.toMatchObject({ reason: 'runtimeNotInstalled' })

  const release = join(root, '1.0')
  await mkdir(release, { recursive: true })
  await writeFile(join(release, command), 'server', { mode: 0o755 })
  await writeFile(join(release, 'harness'), 'harness', { mode: 0o755 })
  await writeFile(
    join(release, RUNTIME_RELEASE_RECEIPT),
    JSON.stringify({
      releaseId: pin.archiveSha256,
      version: '1.0',
      platform: process.platform,
      arch: process.arch,
      members: pin.members.map(({ path, bytes }) => ({ path, bytes }))
    })
  )
  await writeFile(join(localBin, 'harness'), '', { mode: 0o755 })
  expect(await spawn()).toBe(join(release, command))

  await truncate(join(release, command), 2)
  expect(await spawn()).toBe(await realpath(join(localBin, command)))
  await rm(dataDirectory, { recursive: true, force: true })
})

it('writes the captured Windows OMP startup through the provider reader', async () => {
    const reader = new AcpStructuredOptions()
    reader.adoptSession(response)
    expect(reader.read()).toEqual({
      models: [],
      current: { effort: 'off', confirmed: ['effort'] }
    })
    expect(reader.reported()).toEqual({ effort: 'off' })
    expect(writtenOptions('omp', reader)).toEqual({ effort: 'off' })
  })

it.each(['grok', 'opencode'])('writes missing-model options for %s', async (provider) => {
    const reader = new AcpStructuredOptions()
    reader.adoptSession({})
    expect(reader.read().current).not.toHaveProperty('model')
    expect(writtenOptions(provider, reader)).toEqual({})
  })

it.each(['config', 'legacy'] as const)('does not expose an empty %s model value', (source) => {
    const reader = new AcpStructuredOptions()
    reader.adoptSession(
      source === 'config'
        ? { configOptions: [{ ...modelOption, currentValue: '', options: [] }] }
        : { models: { currentModelId: '', availableModels: [] } }
    )
    expect(reader.read().current).not.toHaveProperty('model')
    expect(reader.reported()).toEqual({})
  })

it('records a model reported after a startup with no model', async () => {
    const reader = new AcpStructuredOptions()
    reader.adoptSession(response)
    expect(writtenOptions('omp', reader)).toEqual({ effort: 'off' })
    reader.adoptConfigOptions([...(response.configOptions ?? []), modelOption])
    expect(reader.read().current).toEqual({
      model: 'reported-model',
      effort: 'off',
      confirmed: ['model', 'effort']
    })
    expect(writtenOptions('omp', reader)).toEqual({ model: 'reported-model', effort: 'off' })
  })

it.each(['omp-v17-reply-without-thought', 'omp-v17-reply-after-thought'])(
    'keeps both ordinary answers from %s',
    async (name) => {
      const frames = await readAcpFixture(name)
      const replay = new GrokFixtureReplay(frames)
      const rig = await openAcpAdapterRig({
        spec: acpLaunchSpecFor('omp')!,
        script: (scripted) => replay.attach(scripted)
      })
      await rig.acquire()
      await rig.adapter.dispatch({
        sessionId: SESSION,
        clientMessageId: 'send-1',
        body: ask,
        fence: 1
      })
      await waitFor(async () => expect(await turns(rig)).toHaveLength(1))
      await rig.adapter.dispatch({
        sessionId: SESSION,
        clientMessageId: 'send-2',
        body: ask,
        fence: 1
      })
      await waitFor(() => expect(replay.awaiting).toBeNull())
      await waitFor(async () => expect(await turns(rig)).toHaveLength(2))
      const recordedAnswers = frames
        .flatMap((frame) => {
          const parsed = SessionNotificationSchema.safeParse(frame.message.params)
          const update = parsed.data?.update
          return update?.sessionUpdate === 'agent_message_chunk' && update.content.type === 'text'
            ? [update.content.text]
            : []
        })
        .join('')
      const rows = await rig.rig.rows()
      const answers = rows
        .flatMap((row) =>
          row.body.kind === 'message' && row.body.role === 'assistant'
            ? row.body.blocks.flatMap((block) => (block.type === 'text' ? [block.text] : []))
            : []
        )
        .join('')
      expect(await turns(rig)).toMatchObject([
        { state: 'completed', outcome: 'success' },
        { state: 'completed', outcome: 'success' }
      ])
      expect(answers).toBe(recordedAnswers)
      if (name === 'omp-v17-reply-after-thought') {
        expect(
          rows.filter((row) => row.body.kind === 'message' && row.body.role === 'reasoning')
        ).toHaveLength(1)
      }
      await rig.adapter.closeSession(SESSION)
      const savedMessages = (await rig.rig.rows()).filter((row) => row.body.kind === 'message')
      const reopened = await rig.rig.reopenJournal()
      expect(reopened.snapshot().items.filter((row) => row.body.kind === 'message')).toEqual(
        savedMessages
      )
    }
  )

it("a failed command's row shows its output and exit code, not the command again", async () => {
    const { rig, replay } = await replaying('omp-v17-shell-exit-3')
    await allowOnce(rig, replay)
    await waitFor(() => expect(replay.awaiting).toBeNull())
    await waitFor(async () =>
      expect(await turns(rig)).toMatchObject([{ state: 'completed', outcome: 'success' }])
    )
    expect(await toolRow(rig)).toMatchObject({
      state: 'failed',
      input: { command: 'printf hi; exit 3' },
      exitCode: 3,
      output: { head: 'hi', truncated: false }
    })
  })

it("a successful command's row shows its output and exit code 0", async () => {
    const { rig, replay } = await replaying('omp-v17-shell-ok')
    await allowOnce(rig, replay)
    await waitFor(() => expect(replay.awaiting).toBeNull())
    await waitFor(async () =>
      expect(await turns(rig)).toMatchObject([{ state: 'completed', outcome: 'success' }])
    )
    // OMP reports an exit code only when it is not zero; a completed foreground command exited 0.
    expect(await toolRow(rig)).toMatchObject({
      state: 'completed',
      exitCode: 0,
      output: { head: 'ok', truncated: false }
    })
  })

it('Stop during a running command ends the turn and leaves the row without the command as output', async () => {
    const { rig, replay } = await replaying('omp-v17-stop-mid-tool')
    await allowOnce(rig, replay)
    await waitFor(() => expect(replay.awaiting).toBe('session/cancel'))
    await expect(rig.adapter.cancelTurn({ sessionId: SESSION, fence: 1 })).resolves.toEqual({
      cancelled: true
    })
    await waitFor(() => expect(replay.awaiting).toBeNull())
    await waitFor(async () =>
      expect(await turns(rig)).toMatchObject([{ state: 'interrupted', outcome: 'cancellation' }])
    )
    // OMP sends nothing more for the stopped command; Orca settles its row with the turn.
    const tool = await toolRow(rig)
    expect(tool).toMatchObject({
      endedAs: 'interrupted',
      input: { command: 'sleep 30', timeout: 60 }
    })
    expect(tool).not.toHaveProperty('output')
  })

